const STORE_KEY = "habitTracker";

function pad2(value) {
  return String(value).padStart(2, "0");
}

function todayKey(date) {
  const d = date || new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function formatTodayLabel(date) {
  const d = date || new Date();
  const weekdays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  return d.getMonth() + 1 + "月" + d.getDate() + "日 " + weekdays[d.getDay()];
}

function makeId() {
  return "h_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

function normalizeHabit(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const habit = Object.assign({}, source);
  if (typeof habit.id !== "string" || habit.id === "") {
    habit.id = makeId();
  }
  if (typeof habit.name !== "string") {
    habit.name = habit.name == null ? "" : String(habit.name);
  }
  if (!Array.isArray(habit.doneDates)) {
    habit.doneDates = [];
  } else {
    habit.doneDates = habit.doneDates.filter(function (item) {
      return typeof item === "string" && item !== "";
    });
  }
  if (typeof habit.createdAt !== "string" || habit.createdAt === "") {
    habit.createdAt = new Date().toISOString();
  }
  return habit;
}

function normalizeState(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const next = Object.assign({}, source);
  const list = Array.isArray(source.habits) ? source.habits : [];
  next.habits = list.map(normalizeHabit);
  return next;
}

const app = document.getElementById("app");

const els = {
  todayDate: app.querySelector('[data-role="today-date"]'),
  doneCount: app.querySelector('[data-role="done-count"]'),
  totalCount: app.querySelector('[data-role="total-count"]'),
  progressFill: app.querySelector('[data-role="progress-fill"]'),
  statHint: app.querySelector('[data-role="stat-hint"]'),
  form: app.querySelector('[data-role="habit-form"]'),
  input: app.querySelector('[data-role="habit-input"]'),
  addBtn: app.querySelector('[data-role="add-btn"]'),
  formError: app.querySelector('[data-role="form-error"]'),
  list: app.querySelector('[data-role="habit-list"]'),
  listCount: app.querySelector('[data-role="list-count"]'),
  emptyState: app.querySelector('[data-role="empty-state"]'),
  saveError: app.querySelector('[data-role="save-error"]'),
  backdrop: app.querySelector('[data-role="dialog-backdrop"]'),
  dialogTitle: app.querySelector('[data-role="dialog-title"]'),
  dialogText: app.querySelector('[data-role="dialog-text"]'),
  dialogCancel: app.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: app.querySelector('[data-role="dialog-confirm"]')
};

let state = { habits: [] };
let pendingDeleteId = null;
let dialogResolver = null;

function isDoneToday(habit) {
  return habit.doneDates.indexOf(todayKey()) !== -1;
}

function render() {
  const habits = state.habits;
  const total = habits.length;
  let done = 0;
  for (let i = 0; i < habits.length; i += 1) {
    if (isDoneToday(habits[i])) {
      done += 1;
    }
  }

  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  els.listCount.textContent = "共 " + total + " 个";
  els.progressFill.style.width = total === 0 ? "0%" : Math.round((done / total) * 100) + "%";

  if (total === 0) {
    els.statHint.textContent = "还没有习惯，先添加一个吧";
  } else if (done === total) {
    els.statHint.textContent = "今天的习惯全部完成，太棒了！";
  } else {
    els.statHint.textContent = "今天还有 " + (total - done) + " 个习惯待完成";
  }

  els.list.textContent = "";
  for (let i = 0; i < habits.length; i += 1) {
    els.list.appendChild(buildRow(habits[i]));
  }

  els.emptyState.hidden = total !== 0;
}

function buildRow(habit) {
  const done = isDoneToday(habit);

  const li = document.createElement("li");
  li.className = "habit-item" + (done ? " is-done" : "");
  li.dataset.habitId = habit.id;

  const label = document.createElement("label");
  label.className = "habit-check";

  const checkbox = document.createElement("input");
  checkbox.type = "checkbox";
  checkbox.className = "habit-checkbox";
  checkbox.checked = done;
  checkbox.dataset.role = "toggle";
  checkbox.dataset.habitId = habit.id;
  checkbox.setAttribute("aria-label", "标记今天完成：" + habit.name);

  const name = document.createElement("span");
  name.className = "habit-name";
  name.textContent = habit.name;

  label.appendChild(checkbox);
  label.appendChild(name);

  const status = document.createElement("span");
  status.className = "habit-status";
  status.textContent = done ? "今天已完成" : "今天未完成";

  const del = document.createElement("button");
  del.type = "button";
  del.className = "btn-delete";
  del.textContent = "删除";
  del.dataset.role = "delete";
  del.dataset.habitId = habit.id;
  del.setAttribute("aria-label", "删除习惯：" + habit.name);

  li.appendChild(label);
  li.appendChild(status);
  li.appendChild(del);
  return li;
}

function showFormError(message) {
  els.formError.textContent = message || "";
}

function showSaveError(message) {
  els.saveError.textContent = message || "";
}

async function persist(nextState) {
  try {
    await appStore.setState(nextState);
    showSaveError("");
    return true;
  } catch (error) {
    showSaveError("保存失败，请重试。你的输入已保留。");
    return false;
  }
}

function openConfirmDialog(habitName) {
  els.dialogTitle.textContent = "确认删除";
  els.dialogText.textContent = "确定要删除习惯“" + habitName + "”吗？删除后该习惯的打卡记录也会一并移除。";
  els.backdrop.hidden = false;
  els.dialogConfirm.focus();
  return new Promise(function (resolve) {
    dialogResolver = resolve;
  });
}

function closeConfirmDialog(result) {
  els.backdrop.hidden = true;
  const resolver = dialogResolver;
  dialogResolver = null;
  if (resolver) {
    resolver(result);
  }
}

async function handleAdd(event) {
  event.preventDefault();
  const raw = els.input.value;
  const name = raw.trim();
  if (name === "") {
    showFormError("请输入习惯名称。");
    els.input.focus();
    return;
  }
  showFormError("");

  const habit = normalizeHabit({ id: makeId(), name: name, doneDates: [], createdAt: new Date().toISOString() });
  const next = Object.assign({}, state, { habits: state.habits.concat([habit]) });
  const ok = await persist(next);
  if (!ok) {
    return;
  }
  state = next;
  els.input.value = "";
  render();
  els.input.focus();
}

async function handleToggle(habitId, checked) {
  const key = todayKey();
  let changed = false;
  const habits = state.habits.map(function (habit) {
    if (habit.id !== habitId) {
      return habit;
    }
    const dates = habit.doneDates.slice();
    const index = dates.indexOf(key);
    if (checked && index === -1) {
      dates.push(key);
      changed = true;
    } else if (!checked && index !== -1) {
      dates.splice(index, 1);
      changed = true;
    }
    return Object.assign({}, habit, { doneDates: dates });
  });

  if (!changed) {
    render();
    return;
  }

  const next = Object.assign({}, state, { habits: habits });
  const ok = await persist(next);
  if (!ok) {
    render();
    return;
  }
  state = next;
  render();
}

async function handleDelete(habitId) {
  const habit = state.habits.filter(function (item) {
    return item.id === habitId;
  })[0];
  if (!habit) {
    return;
  }
  const confirmed = await openConfirmDialog(habit.name);
  if (!confirmed) {
    return;
  }
  const next = Object.assign({}, state, {
    habits: state.habits.filter(function (item) {
      return item.id !== habitId;
    })
  });
  const ok = await persist(next);
  if (!ok) {
    return;
  }
  state = next;
  render();
}

function bindEvents() {
  els.form.addEventListener("submit", function (event) {
    handleAdd(event);
  });

  els.input.addEventListener("input", function () {
    if (els.formError.textContent !== "") {
      showFormError("");
    }
  });

  els.list.addEventListener("change", function (event) {
    const target = event.target;
    if (!target || target.dataset.role !== "toggle") {
      return;
    }
    handleToggle(target.dataset.habitId, target.checked);
  });

  els.list.addEventListener("click", function (event) {
    const target = event.target;
    if (!target || target.dataset.role !== "delete") {
      return;
    }
    handleDelete(target.dataset.habitId);
  });

  els.dialogCancel.addEventListener("click", function () {
    closeConfirmDialog(false);
  });

  els.dialogConfirm.addEventListener("click", function () {
    closeConfirmDialog(true);
  });

  els.backdrop.addEventListener("click", function (event) {
    if (event.target === els.backdrop) {
      closeConfirmDialog(false);
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.backdrop.hidden) {
      closeConfirmDialog(false);
    }
  });
}

async function init() {
  els.todayDate.textContent = formatTodayLabel();

  let raw = null;
  try {
    raw = await appStore.getState();
  } catch (error) {
    raw = null;
  }

  const source = raw && typeof raw === "object" ? raw : {};
  const hasKey = Object.prototype.hasOwnProperty.call(source, STORE_KEY);

  if (hasKey && source[STORE_KEY] && typeof source[STORE_KEY] === "object") {
    state = normalizeState(source[STORE_KEY]);
  } else {
    state = { habits: [] };
    const seeded = Object.assign({}, source);
    seeded[STORE_KEY] = state;
    try {
      await appStore.setState(seeded);
    } catch (error) {
      showSaveError("初始化存储失败，本次改动可能无法保存。");
    }
  }

  bindEvents();
  render();
}

await init();

