:root {
  --bg-deep: #101a2b;
  --bg-mid: #16233a;
  --surface: rgba(255, 255, 255, 0.06);
  --surface-strong: rgba(255, 255, 255, 0.1);
  --border-soft: rgba(255, 255, 255, 0.14);
  --text-main: #eef4ff;
  --text-muted: #a3b2cc;
  --accent: #4fd1a5;
  --accent-strong: #2fb98c;
  --accent-soft: rgba(79, 209, 165, 0.16);
  --danger: #ff7a7a;
  --danger-soft: rgba(255, 122, 122, 0.16);
  --shadow: 0 18px 40px rgba(4, 10, 22, 0.45);
  --radius-lg: 18px;
  --radius-md: 12px;
  --radius-sm: 9px;
}

#app {
  min-height: 100vh;
  background:
    radial-gradient(1100px 620px at 12% -10%, rgba(79, 209, 165, 0.18), transparent 60%),
    radial-gradient(900px 560px at 100% 0%, rgba(96, 140, 255, 0.2), transparent 62%),
    linear-gradient(180deg, var(--bg-deep) 0%, var(--bg-mid) 55%, #0d1626 100%);
  color: var(--text-main);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-height: 100vh;
}

.app-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.app-title {
  margin: 0;
  font-size: 28px;
  letter-spacing: 0.5px;
  color: var(--text-main);
}

.app-subtitle {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: 14px;
}

.today-badge {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  padding: 10px 16px;
  border-radius: var(--radius-md);
  background: var(--surface);
  border: 1px solid var(--border-soft);
}

.today-label {
  font-size: 12px;
  color: var(--text-muted);
  letter-spacing: 2px;
}

.today-date {
  font-size: 15px;
  font-weight: 600;
  color: var(--accent);
}

.stats-panel {
  background: var(--surface);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat-main {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.stat-number {
  font-size: 40px;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
}

.stat-unit {
  font-size: 15px;
  color: var(--text-muted);
}

.stat-bar {
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
  overflow: hidden;
}

.stat-bar-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent));
  transition: width 0.28s ease;
}

.stat-hint {
  margin: 0;
  font-size: 13px;
  color: var(--text-muted);
}

.form-panel {
  background: var(--surface);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-lg);
  padding: 20px;
}

.habit-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.field-label {
  font-size: 13px;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

.field-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.field-input {
  flex: 1 1 220px;
  min-width: 0;
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-soft);
  background: rgba(9, 16, 28, 0.6);
  color: var(--text-main);
  font-size: 15px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.field-input::placeholder {
  color: rgba(163, 178, 204, 0.7);
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.btn {
  font-family: inherit;
  font-size: 15px;
  padding: 12px 20px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
  color: #06231a;
  font-weight: 600;
}

.btn-primary:hover {
  filter: brightness(1.06);
}

.btn-ghost {
  background: transparent;
  border-color: var(--border-soft);
  color: var(--text-muted);
}

.btn-ghost:hover {
  color: var(--text-main);
  border-color: rgba(255, 255, 255, 0.3);
}

.btn-danger {
  background: var(--danger);
  color: #2b0b0b;
  font-weight: 600;
}

.btn-danger:hover {
  filter: brightness(1.06);
}

.form-error {
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
}

.list-panel {
  background: var(--surface);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.list-title {
  margin: 0;
  font-size: 17px;
  color: var(--text-main);
}

.list-count {
  font-size: 13px;
  color: var(--text-muted);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  background: rgba(9, 16, 28, 0.45);
  border: 1px solid var(--border-soft);
  transition: border-color 0.2s ease, background 0.2s ease;
}

.habit-item.is-done {
  border-color: rgba(79, 209, 165, 0.55);
  background: var(--accent-soft);
}

.habit-check {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  cursor: pointer;
}

.habit-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  border-radius: 7px;
  border: 2px solid rgba(255, 255, 255, 0.35);
  background: rgba(9, 16, 28, 0.7);
  cursor: pointer;
  position: relative;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.habit-checkbox:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.habit-checkbox:checked::after {
  content: "";
  position: absolute;
  left: 6px;
  top: 2px;
  width: 6px;
  height: 11px;
  border: solid #06231a;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.habit-checkbox:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.habit-name {
  font-size: 15px;
  color: var(--text-main);
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: #d8fff1;
}

.habit-status {
  font-size: 12px;
  color: var(--text-muted);
  white-space: nowrap;
}

.habit-item.is-done .habit-status {
  color: var(--accent);
}

.btn-delete {
  flex: 0 0 auto;
  background: transparent;
  border: 1px solid var(--border-soft);
  color: var(--text-muted);
  font-size: 13px;
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-family: inherit;
  transition: color 0.2s ease, border-color 0.2s ease, background 0.2s ease;
}

.btn-delete:hover {
  color: var(--danger);
  border-color: var(--danger);
  background: var(--danger-soft);
}

.empty-state {
  padding: 26px 18px;
  border-radius: var(--radius-md);
  border: 1px dashed var(--border-soft);
  text-align: center;
  color: var(--text-muted);
}

.empty-state[hidden] {
  display: none;
}

.empty-title {
  margin: 0 0 6px;
  font-size: 15px;
  color: var(--text-main);
}

.empty-desc {
  margin: 0;
  font-size: 13px;
}

.save-error {
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
  text-align: center;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5, 10, 20, 0.68);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: #16233a;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-lg);
  padding: 22px;
  box-shadow: var(--shadow);
  color: var(--text-main);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-muted);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 480px) {
  .app-shell {
    padding: 24px 14px 48px;
  }

  .app-title {
    font-size: 24px;
  }

  .stat-number {
    font-size: 34px;
  }

  .field-row {
    flex-direction: column;
  }

  .btn-primary {
    width: 100%;
  }
}
